// === Tab: mySketch ===
let particles = [];
let cols, rows;
let spacing = 8;
let particleCount;
let glowRadius = 80;
let waves = [];
let waveInterval = 180;
let frameCounter = 0;
let oceanTime = 0;
let colorModeToggle = 0;
let slider;
let useOceanBreathing = true; // Toggle for ocean breathing effect

function setup() {
  createCanvas(600, 640); // Extra height for slider
  colorMode(HSB, 360, 100, 100, 255);

  // Create slider for color scheme
  slider = createSlider(0, 1, 0, 0.1);
  slider.position(20, height - 30);
  slider.style('width', '200px');
  slider.style('accent-color', '#4FC3F7');

  let label = createP('Classic ← → Ocean');
  label.position(230, height - 48);
  label.style('color', '#FFFFFF');
  label.style('font-family', 'Arial');
  label.style('font-size', '12px');
  label.style('margin', '0');
  label.style('opacity', '0.7');

  // Breathing toggle - press 'B' to toggle
  let toggleLabel = createP('Press B to toggle the mosaic breath: ON');
  toggleLabel.position(20, height - 70);
  toggleLabel.style('color', '#FFFFFF');
  toggleLabel.style('font-family', 'Arial');
  toggleLabel.style('font-size', '12px');
  toggleLabel.style('margin', '0');
  toggleLabel.style('opacity', '0.7');
  toggleLabel.id('toggleLabel');

  cols = floor(width / spacing) + 1;
  rows = floor(height / spacing) + 1;
  particleCount = cols * rows;

  for (let i = 0; i < particleCount; i++) {
    let x = (i % cols) * spacing;
    let y = floor(i / cols) * spacing;
    x += random(-2, 2);
    y += random(-2, 2);
    particles.push(new Particle(x, y));
  }
}

function draw() {
  oceanTime += 0.005;
  background(0, 0, 0, 25);

  colorModeToggle = slider.value();

  updateWaves();

  for (let p of particles) {
    p.update();
    p.display();
  }
}

function keyPressed() {
  if (key === 'b' || key === 'B') {
    useOceanBreathing = !useOceanBreathing;
    var label = document.getElementById('toggleLabel');
    if (label) {
      label.innerHTML = 'Press B to toggle the mosaic breath: ' + (useOceanBreathing ? 'ON' : 'OFF');
    }
  }
}

function updateWaves() {
  frameCounter++;
  if (frameCounter >= waveInterval) {
    frameCounter = 0;
    waveInterval = floor(random(100, 280));

    // Randomly choose wave type
    let waveType = random();
    let wave;

    if (waveType < 0.35) {
      // Circular wave
      wave = {
        type: 'circle',
        originX: random(width * 0.15, width * 0.85),
        originY: random(height * 0.15, height * 0.85),
        radius: 0,
        maxRadius: random(width * 0.5, width * 1.3),
        speed: random(1.5, 3.5),
        life: 255,
        decay: random(0.5, 1.5),
        hue: random(360),
        width: random(15, 40),
        phase: random(TWO_PI)
      };
    } else if (waveType < 0.7) {
      // Sin-like wave with washing effect
      wave = {
        type: 'sin',
        originX: random(width * 0.1, width * 0.9),
        originY: random(height * 0.1, height * 0.9),
        angle: random(TWO_PI),
        wavelength: random(40, 120),
        amplitude: random(30, 100),
        speed: random(1, 3),
        life: 255,
        decay: random(0.3, 1.2),
        hue: random(360),
        baseWidth: random(12, 35),
        phase: random(TWO_PI),
        direction: random([-1, 1]),
        // Fluctuation properties
        widthFluctuation: random(0.5, 2.0),
        areaFluctuation: random(0.3, 1.5),
        washSpeed: random(0.02, 0.08),
        washPhase: random(TWO_PI),
        // Washing across the canvas
        washDirection: random([-1, 1]),
        washOffset: 0,
        // Growth properties
        growth: 0,
        maxGrowth: random(1.2, 2.5),
        growthSpeed: random(0.005, 0.02)
      };
    } else {
      // Dash wave
      wave = {
        type: 'dash',
        originX: random(width * 0.1, width * 0.9),
        originY: random(height * 0.1, height * 0.9),
        angle: random(TWO_PI),
        length: random(60, 200),
        speed: random(2, 5),
        life: 255,
        decay: random(0.5, 1.8),
        hue: random(360),
        width: random(20, 50),
        dashCount: floor(random(5, 15)),
        phase: random(TWO_PI),
        spread: random(30, 80)
      };
    }
    waves.push(wave);
  }

  // Update existing waves
  for (let i = waves.length - 1; i >= 0; i--) {
    let w = waves[i];

    if (w.type === 'circle') {
      w.radius += w.speed;
    } else if (w.type === 'sin') {
      // Update sine wave with washing effect
      w.phase += 0.05 * w.speed;

      // Wash across the canvas - move the origin
      w.washOffset += w.washSpeed * w.washDirection;

      // Fluctuate amplitude and width
      w.currentAmplitude = w.amplitude * (1 + 0.3 * sin(frameCount * 0.02 + w.areaFluctuation));
      w.currentWidth = w.baseWidth * (1 + 0.4 * sin(frameCount * 0.03 + w.widthFluctuation));

      // Grow the wave for washing effect
      w.growth = min(w.growth + w.growthSpeed, w.maxGrowth);

      // Move the wave in its direction for washing
      w.originX += sin(w.angle + w.washPhase) * 0.5 * w.washDirection;
      w.originY += cos(w.angle + w.washPhase) * 0.5 * w.washDirection;

      // Change angle slowly for sweeping effect
      w.angle += 0.002 * w.washDirection;
    } else if (w.type === 'dash') {
      w.phase += 0.08 * w.speed;
      w.originX += sin(w.phase * 0.3 + w.angle) * 0.5;
      w.originY += cos(w.phase * 0.4 + w.angle) * 0.5;
    }

    w.life -= w.decay;

    if (w.life <= 0 || (w.type === 'circle' && w.radius > w.maxRadius)) {
      waves.splice(i, 1);
    }
  }
}

class Particle {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    // Classic colors - bright and vibrant
    this.hue = random(360);
    this.sat = random(60, 100);
    this.bri = random(80, 100);
    this.size = random(3, 7);
    this.shimmerSpeed = random(0.02, 0.08);
    this.shimmerOffset = random(TWO_PI);
    this.flickerSpeed = random(0.03, 0.1);
    this.flickerOffset = random(TWO_PI);
    this.baseAlpha = random(150, 255);
    this.originalBri = this.bri;
    this.originalAlpha = this.baseAlpha;

    // Ocean colors - more subdued
    this.oceanHue = random(180, 260);
    this.oceanSat = random(40, 80);
    this.oceanBri = random(50, 80);

    // Ocean depth based on position (deeper = darker)
    this.depthFactor = map(this.y, 0, height, 0.3, 1.0);
    this.depthOffset = random(-0.1, 0.1);

    // Unique ocean rhythm
    this.oceanPhase = random(TWO_PI);
    this.oceanSpeed = random(0.005, 0.02);
  }

  update() {
    // OCEAN BREATHING EFFECT - optional, toggled with 'B' key
    let oceanBrightness = 1;
    let oceanHueShift = 0;

    if (useOceanBreathing) {
      // 1. Deep ocean waves - slow brightness pulses
      let deepPulse = 0.7 + 0.3 * sin(oceanTime * 0.3 + this.oceanPhase + this.y * 0.01);

      // 2. Surface ripple effect - faster, smaller variations
      let surfaceRipple = 0.85 + 0.15 * sin(oceanTime * 0.8 + this.x * 0.02 + this.y * 0.015 + this.shimmerOffset);

      // 3. Depth-based darkening (deeper = darker like ocean)
      let depthBrightness = 0.6 + 0.4 * (1 - this.depthFactor);

      // 4. Tide effect - slow shifting across the canvas
      let tideX = sin(oceanTime * 0.2 + this.x * 0.005) * 0.1;
      let tideY = cos(oceanTime * 0.15 + this.y * 0.005) * 0.1;
      let tideEffect = 0.9 + tideX + tideY;

      // 5. Color shifting - subtle hue changes like ocean light
      oceanHueShift = 5 * sin(oceanTime * 0.1 + this.x * 0.005 + this.y * 0.005);

      // Combine all ocean effects
      oceanBrightness = deepPulse * surfaceRipple * depthBrightness * tideEffect;
    }

    // Interpolate between classic and ocean based on slider
    let mix = colorModeToggle;

    // Mix colors
    let currentHue = lerp(this.hue, this.oceanHue, mix);
    let currentSat = lerp(this.sat, this.oceanSat, mix);
    let currentBri = lerp(this.originalBri, this.oceanBri, mix);

    // Apply ocean breathing to brightness if enabled
    let oceanAdjustedBri = currentBri * oceanBrightness;

    // Dark glow from mouse
    let d = dist(this.x, this.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let glowFactor = 1;
    if (d < glowRadius) {
      let intensity = 1 - (d / glowRadius);
      intensity = pow(intensity, 1.5);
      glowFactor = 1 - (intensity * 0.85);
    }

    let waveBrightness = 1;
    let waveAlphaBoost = 1;
    let waveHueShift = 0;

    for (let w of waves) {
      let effect = false;
      let positionInWave = 0;
      let waveHue = w.hue;

      if (w.type === 'circle') {
        let distToWave = dist(this.x, this.y, w.originX, w.originY);
        let distFromEdge = abs(distToWave - w.radius);

        if (distFromEdge < w.width) {
          effect = true;
          positionInWave = 1 - (distFromEdge / w.width);
          positionInWave = pow(positionInWave, 0.8);
        }
      } else if (w.type === 'sin') {
        // Enhanced sin wave with fluctuating width and washing
        let dx = this.x - w.originX;
        let dy = this.y - w.originY;
        let localX = dx * cos(-w.angle) - dy * sin(-w.angle);
        let localY = dx * sin(-w.angle) + dy * cos(-w.angle);

        // Calculate sine wave with fluctuating amplitude
        let waveValue = sin(localX / w.wavelength * TWO_PI + w.phase);
        let waveY = waveValue * w.currentAmplitude * w.growth;

        // Calculate distance from wave with fluctuating width
        let distFromWave = abs(localY - waveY);
        let currentWidth = w.currentWidth * w.growth;

        if (distFromWave < currentWidth) {
          effect = true;
          positionInWave = 1 - (distFromWave / currentWidth);
          positionInWave = pow(positionInWave, 0.9);

          // Bonus brightness for being at wave peaks
          let peakBonus = 1 + abs(waveValue) * 0.5;
          positionInWave *= peakBonus;
        }
      } else if (w.type === 'dash') {
        var dx = this.x - w.originX;
        var dy = this.y - w.originY;
        var localX = dx * cos(-w.angle) - dy * sin(-w.angle);
        var localY = dx * sin(-w.angle) + dy * cos(-w.angle);

        let dashPosition = localX + w.phase * 2;
        let dashInterval = w.length / w.dashCount;
        let dashIndex = floor(dashPosition / dashInterval);
        let withinDash = (dashIndex % 2 === 0);

        if (withinDash) {
          let distFromLine = abs(localY);
          let distFromDashCenter = abs(dashPosition - dashIndex * dashInterval - dashInterval/2);
          let dashHalfWidth = dashInterval * 0.4;

          if (distFromLine < w.width && distFromDashCenter < dashHalfWidth) {
            effect = true;
            let distFromEdgeX = 1 - (distFromDashCenter / dashHalfWidth);
            let distFromEdgeY = 1 - (distFromLine / w.width);
            positionInWave = min(distFromEdgeX, distFromEdgeY) * 0.8 + 0.2;
            positionInWave = pow(positionInWave, 0.7);
          }
        }
      }

      if (effect) {
        let waveBoost = 1 + positionInWave * 3.5;
        waveBrightness = max(waveBrightness, waveBoost);

        let alphaBoost = 1 + positionInWave * 1.8;
        waveAlphaBoost = max(waveAlphaBoost, alphaBoost);

        let hueShiftAmount = (waveHue - currentHue) * positionInWave * 0.4;
        waveHueShift += hueShiftAmount;
      }
    }

    // Shimmer effect - exactly as in classic
    let shimmer = 0.6 + 0.4 * sin(frameCount * this.shimmerSpeed + this.shimmerOffset);
    this.currentBri = oceanAdjustedBri * shimmer * glowFactor * waveBrightness;

    // Flicker effect - exactly as in classic
    let flicker = 0.7 + 0.3 * sin(frameCount * this.flickerSpeed + this.flickerOffset);
    let alphaGlow = glowFactor;
    this.currentAlpha = this.originalAlpha * flicker * alphaGlow * waveAlphaBoost;

    // Hue with ocean and wave shifts
    this.currentHue = currentHue + oceanHueShift + waveHueShift + 5 * sin(frameCount * 0.01 + this.shimmerOffset);
    this.currentSat = currentSat;

    // Edge glow effect - exactly as in classic
    if (d > glowRadius && d < glowRadius * 2) {
      let edgeGlow = 1 + 0.15 * sin((d - glowRadius) / glowRadius * PI);
      this.currentBri *= edgeGlow;
    }

    // Clamp values
    this.currentBri = min(this.currentBri, 100);
    this.currentAlpha = min(this.currentAlpha, 255);
  }

  display() {
    noStroke();
    fill(this.currentHue % 360, this.currentSat, this.currentBri, this.currentAlpha);

    rectMode(CENTER);
    push();
    translate(this.x, this.y);
    // Classic rotation
    rotate(sin(frameCount * 0.005 + this.shimmerOffset) * 0.3);
    rect(0, 0, this.size, this.size);
    pop();
  }
}

function mousePressed() {
  for (let p of particles) {
    // Regenerate classic colors
    p.hue = random(360);
    p.sat = random(60, 100);
    p.bri = random(80, 100);

    // Regenerate ocean colors
    p.oceanHue = random(180, 260);
    p.oceanSat = random(40, 80);
    p.oceanBri = random(50, 80);

    p.originalBri = p.bri;
    p.originalAlpha = p.baseAlpha;
    p.oceanPhase = random(TWO_PI);
  }
}

function mouseWheel(event) {
  glowRadius = constrain(glowRadius + event.delta * 0.2, 30, 200);
  return false;
}

